# ---- sheyang.observed / wind / rain : scoped convective "待确认"->"已确认" ----
def scrub(s):
    s = s.replace("2026-10-06 05:50 续报", "2026-10-06 09:09 续报")
    s = s.replace("2026-10-06 05:50", "2026-10-06 09:09")
    # 本地强对流 待确认 -> 已确认
    s = s.replace("8-10级雷暴大风+海区局部10级预报(预报·待确认)", "8-10级雷暴大风+海区局部10级预报(盐城气象10/6微博已确认)")
    s = s.replace("10级左右雷暴大风（强对流·预报待确认）", "10级左右雷暴大风（强对流·盐城气象10/6微博已确认）")
    s = s.replace("(海区局部10级·预报待确认)", "(海区局部10级·盐城气象10/6微博已确认)")
    s = s.replace("8-10级雷暴大风（海区局部10级·预报待确认）", "8-10级雷暴大风（海区局部10级·盐城气象10/6微博已确认）")
    s = s.replace("待盐城/射阳气象台临近预报或正式预警确认", "盐城气象10/6微博已确认、以临近预报为准")
    return s

for k in ("observed", "wind", "rain"):
    if isinstance(d["sheyang"].get(k), str):
        d["sheyang"][k] = scrub(d["sheyang"][k])

